{-| @Backend.Runtime.Kernel.Json — the JSON reader and writer over `Std.Json.Json` boxes. -}
module Pudu.Backend.Runtime.Kernel.Json (jsonKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
jsonKernelParts :: [(Text, [Text], [Text])]
jsonKernelParts =
  [ ("json_reader", ["array", "array_reserve", "text_allocate", "kernel_int"],
      [ "/* A JSON text and the Json variants' indexes. A reader walks the text twice:"
      , "   once to accept it, once to build, so nothing built is ever abandoned. */"
      , "typedef struct { const unsigned char *bytes; size_t size; int null_tag, boolean_tag, number_tag, fractional_tag, text_tag, list_tag, object_tag; } pudu_json;"
      , "static size_t pudu_json_space(const pudu_json *in, size_t at) {"
      , "  while (at < in->size && (in->bytes[at] == 32 || in->bytes[at] == 9 || in->bytes[at] == 13 || in->bytes[at] == 10)) at += 1;"
      , "  return at;"
      , "}"
      , "static size_t pudu_json_digits(const pudu_json *in, size_t at) {"
      , "  while (at < in->size && in->bytes[at] >= 48 && in->bytes[at] <= 57) at += 1;"
      , "  return at;"
      , "}"
      , "/* Four hex digits, or -1. */"
      , "static long pudu_json_hex(const pudu_json *in, size_t at) {"
      , "  long value = 0;"
      , "  if (at > in->size || in->size - at < 4) return -1;"
      , "  for (int i = 0; i < 4; ++i) {"
      , "    unsigned char byte = in->bytes[at + i], lower = byte | 0x20;"
      , "    if (byte >= 48 && byte <= 57) value = value * 16 + (byte - 48);"
      , "    else if (lower >= 97 && lower <= 102) value = value * 16 + (lower - 87);"
      , "    else return -1;"
      , "  }"
      , "  return value;"
      , "}"
      , "/* The string opening at a quote: its decoded bytes into out when out is"
      , "   there, their count, and the position past the closing quote. */"
      , "static int pudu_json_string(const pudu_json *in, size_t at, unsigned char *out, size_t *length, size_t *next) {"
      , "  size_t written = 0;"
      , "  for (at += 1;;) {"
      , "    unsigned char byte;"
      , "    long scalar;"
      , "    if (at >= in->size) return 0;"
      , "    byte = in->bytes[at];"
      , "    if (byte == 34) break;"
      , "    if (byte < 32) return 0;"
      , "    if (byte != 92) {"
      , "      if (out != NULL) out[written] = byte;"
      , "      written += 1;"
      , "      at += 1;"
      , "      continue;"
      , "    }"
      , "    if (at + 1 >= in->size) return 0;"
      , "    byte = in->bytes[at + 1];"
      , "    at += 2;"
      , "    switch (byte) {"
      , "      case 34: scalar = '\"'; break;"
      , "      case 92: scalar = '\\\\'; break;"
      , "      case 47: scalar = '/'; break;"
      , "      case 98: scalar = 8; break;"
      , "      case 102: scalar = 12; break;"
      , "      case 110: scalar = 10; break;"
      , "      case 114: scalar = 13; break;"
      , "      case 116: scalar = 9; break;"
      , "      case 117:"
      , "        scalar = pudu_json_hex(in, at);"
      , "        if (scalar < 0 || (scalar >= 0xDC00 && scalar <= 0xDFFF)) return 0;"
      , "        at += 4;"
      , "        if (scalar >= 0xD800 && scalar <= 0xDBFF) {"
      , "          long low;"
      , "          if (in->size - at < 2 || in->bytes[at] != 92 || in->bytes[at + 1] != 117) return 0;"
      , "          low = pudu_json_hex(in, at + 2);"
      , "          if (low < 0xDC00 || low > 0xDFFF) return 0;"
      , "          scalar = 0x10000 + ((scalar - 0xD800) << 10) + (low - 0xDC00);"
      , "          at += 6;"
      , "        }"
      , "        break;"
      , "      default: return 0;"
      , "    }"
      , "    if (scalar < 0x80) {"
      , "      if (out != NULL) out[written] = (unsigned char)scalar;"
      , "      written += 1;"
      , "    } else if (scalar < 0x800) {"
      , "      if (out != NULL) { out[written] = (unsigned char)(0xC0 | (scalar >> 6)); out[written + 1] = (unsigned char)(0x80 | (scalar & 0x3F)); }"
      , "      written += 2;"
      , "    } else if (scalar < 0x10000) {"
      , "      if (out != NULL) {"
      , "        out[written] = (unsigned char)(0xE0 | (scalar >> 12));"
      , "        out[written + 1] = (unsigned char)(0x80 | ((scalar >> 6) & 0x3F));"
      , "        out[written + 2] = (unsigned char)(0x80 | (scalar & 0x3F));"
      , "      }"
      , "      written += 3;"
      , "    } else {"
      , "      if (out != NULL) {"
      , "        out[written] = (unsigned char)(0xF0 | (scalar >> 18));"
      , "        out[written + 1] = (unsigned char)(0x80 | ((scalar >> 12) & 0x3F));"
      , "        out[written + 2] = (unsigned char)(0x80 | ((scalar >> 6) & 0x3F));"
      , "        out[written + 3] = (unsigned char)(0x80 | (scalar & 0x3F));"
      , "      }"
      , "      written += 4;"
      , "    }"
      , "  }"
      , "  *length = written;"
      , "  *next = at + 1;"
      , "  return 1;"
      , "}"
      , "/* The string as owned text; only called on a string already accepted. */"
      , "static pudu_text pudu_json_text(const pudu_json *in, size_t at) {"
      , "  size_t length = 0, next = 0;"
      , "  unsigned char *bytes;"
      , "  pudu_text text;"
      , "  (void)pudu_json_string(in, at, NULL, &length, &next);"
      , "  text = pudu_text_allocate(length, &bytes);"
      , "  (void)pudu_json_string(in, at, bytes, &length, &next);"
      , "  return text;"
      , "}"
      , "static pudu_box *pudu_json_sum(int tag, size_t members) {"
      , "  pudu_box *box = pudu_box_new(1 + members);"
      , "  box->fields[0].scalar = tag;"
      , "  return box;"
      , "}"
      , "static void pudu_json_push(pudu_box *array, pudu_box *member) {"
      , "  pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "  array->fields[0].items->cells[pudu_array_length(array)].box = member;"
      , "  pudu_array_length(array) += 1;"
      , "}"
      , "/* One value at a position. With made absent the text is only checked. */"
      , "static int pudu_json_value(const pudu_json *in, int depth, size_t at, pudu_box **made, size_t *next) {"
      , "  unsigned char byte;"
      , "  if (at >= in->size) return 0;"
      , "  byte = in->bytes[at];"
      , "  if (byte == 34) {"
      , "    size_t length;"
      , "    if (!pudu_json_string(in, at, NULL, &length, next)) return 0;"
      , "    if (made != NULL) { *made = pudu_json_sum(in->text_tag, 1); (*made)->fields[1].text = pudu_json_text(in, at); }"
      , "    return 1;"
      , "  }"
      , "  if ((byte == 91 || byte == 123) && depth < 512) {"
      , "    unsigned char close = byte == 91 ? 93 : 125;"
      , "    pudu_box *members = made == NULL ? NULL : pudu_array_new(0);"
      , "    if (made != NULL) { *made = pudu_json_sum(byte == 91 ? in->list_tag : in->object_tag, 1); (*made)->fields[1].box = members; }"
      , "    at = pudu_json_space(in, at + 1);"
      , "    if (at < in->size && in->bytes[at] == close) { *next = at + 1; return 1; }"
      , "    for (;;) {"
      , "      pudu_box *held = NULL, *entry = NULL;"
      , "      size_t key = at, length;"
      , "      if (byte == 123) {"
      , "        if (at >= in->size || in->bytes[at] != 34 || !pudu_json_string(in, at, NULL, &length, &at)) return 0;"
      , "        at = pudu_json_space(in, at);"
      , "        if (at >= in->size || in->bytes[at] != 58) return 0;"
      , "        at = pudu_json_space(in, at + 1);"
      , "      }"
      , "      if (!pudu_json_value(in, depth + 1, at, made == NULL ? NULL : &held, &at)) return 0;"
      , "      if (made != NULL && byte == 123) {"
      , "        entry = pudu_box_new(2);"
      , "        entry->fields[0].text = pudu_json_text(in, key);"
      , "        entry->fields[1].box = held;"
      , "        held = entry;"
      , "      }"
      , "      if (made != NULL) pudu_json_push(members, held);"
      , "      at = pudu_json_space(in, at);"
      , "      if (at >= in->size) return 0;"
      , "      if (in->bytes[at] == close) { *next = at + 1; return 1; }"
      , "      if (in->bytes[at] != 44) return 0;"
      , "      at = pudu_json_space(in, at + 1);"
      , "    }"
      , "  }"
      , "  if (byte == 116 || byte == 102 || byte == 110) {"
      , "    const char *word = byte == 116 ? \"true\" : byte == 102 ? \"false\" : \"null\";"
      , "    size_t length = strlen(word);"
      , "    if (in->size - at < length || memcmp(in->bytes + at, word, length) != 0) return 0;"
      , "    *next = at + length;"
      , "    if (made != NULL && byte == 110) *made = pudu_json_sum(in->null_tag, 0);"
      , "    else if (made != NULL) { *made = pudu_json_sum(in->boolean_tag, 1); (*made)->fields[1].scalar = byte == 116; }"
      , "    return 1;"
      , "  }"
      , "  if (byte == 45 || (byte >= 48 && byte <= 57)) {"
      , "    size_t digits = byte == 45 ? at + 1 : at, whole = pudu_json_digits(in, digits), end = whole;"
      , "    int plain = 1;"
      , "    uint64_t magnitude = 0;"
      , "    if (whole == digits || (whole - digits > 1 && in->bytes[digits] == 48)) return 0;"
      , "    if (end < in->size && in->bytes[end] == 46) {"
      , "      plain = 0;"
      , "      end = pudu_json_digits(in, whole + 1);"
      , "      if (end == whole + 1) return 0;"
      , "    }"
      , "    if (end < in->size && (in->bytes[end] == 101 || in->bytes[end] == 69)) {"
      , "      size_t power = end + 1 < in->size && (in->bytes[end + 1] == 43 || in->bytes[end + 1] == 45) ? end + 2 : end + 1;"
      , "      plain = 0;"
      , "      end = pudu_json_digits(in, power);"
      , "      if (end == power) return 0;"
      , "    }"
      , "    *next = end;"
      , "    if (!plain) {"
      , "      if (made != NULL) {"
      , "        unsigned char *bytes;"
      , "        *made = pudu_json_sum(in->fractional_tag, 1);"
      , "        (*made)->fields[1].text = pudu_text_allocate(end - at, &bytes);"
      , "        memcpy(bytes, in->bytes + at, end - at);"
      , "      }"
      , "      return 1;"
      , "    }"
      , "    /* A whole number's magnitude must fit the language's Int. */"
      , "    for (size_t i = digits; i < whole; ++i) {"
      , "      uint64_t digit = (uint64_t)(in->bytes[i] - 48);"
      , "      if (magnitude > ((uint64_t)INT64_MAX - digit) / 10) return 0;"
      , "      magnitude = magnitude * 10 + digit;"
      , "    }"
      , "    if (made != NULL) {"
      , "      *made = pudu_json_sum(in->number_tag, 1);"
      , "      (*made)->fields[1].integer = pudu_kernel_int(byte == 45 ? -(int64_t)magnitude : (int64_t)magnitude);"
      , "    }"
      , "    return 1;"
      , "  }"
      , "  return 0;"
      , "}"
      ])
  , ("json_decode", ["json_reader"],
      [ "/* The value filling the whole text apart from whitespace, or no box. */"
      , "static pudu_box *pudu_json_decode(pudu_text source, int null_tag, int boolean_tag, int number_tag, int fractional_tag, int text_tag, int list_tag, int object_tag) {"
      , "  pudu_json in = {source.bytes, source.length, null_tag, boolean_tag, number_tag, fractional_tag, text_tag, list_tag, object_tag};"
      , "  size_t start = pudu_json_space(&in, 0), next = 0;"
      , "  pudu_box *made = NULL;"
      , "  if (!pudu_json_value(&in, 0, start, NULL, &next) || pudu_json_space(&in, next) != in.size) return NULL;"
      , "  (void)pudu_json_value(&in, 0, start, &made, &next);"
      , "  return made;"
      , "}"
      ])
  , ("json_encode", ["array", "text_allocate", "memory_failure", "magnitude"],
      [ "/* A growing byte buffer and the variants' indexes. */"
      , "typedef struct { unsigned char *bytes; size_t length, capacity; int pretty; int null_tag, boolean_tag, number_tag, fractional_tag, text_tag, list_tag; } pudu_json_writer;"
      , "static void pudu_json_write(pudu_json_writer *out, const void *bytes, size_t length) {"
      , "  if (length > SIZE_MAX - out->length) pudu_memory_failure();"
      , "  if (out->length + length > out->capacity) {"
      , "    size_t capacity = out->capacity < 64 ? 64 : out->capacity;"
      , "    while (capacity < out->length + length) capacity = capacity > SIZE_MAX / 2 ? out->length + length : capacity * 2;"
      , "    out->bytes = realloc(out->bytes, capacity);"
      , "    if (out->bytes == NULL) pudu_memory_failure();"
      , "    out->capacity = capacity;"
      , "  }"
      , "  if (length != 0) memcpy(out->bytes + out->length, bytes, length);"
      , "  out->length += length;"
      , "}"
      , "static void pudu_json_line(pudu_json_writer *out, size_t depth) {"
      , "  if (!out->pretty) return;"
      , "  pudu_json_write(out, \"\\n\", 1);"
      , "  for (size_t i = 0; i < depth; ++i) pudu_json_write(out, \"  \", 2);"
      , "}"
      , "/* A JSON string: runs without escapes are written whole. */"
      , "static void pudu_json_quote(pudu_json_writer *out, pudu_text text) {"
      , "  static const char hex[] = \"0123456789abcdef\";"
      , "  size_t from = 0;"
      , "  pudu_json_write(out, \"\\\"\", 1);"
      , "  for (size_t i = 0; i < text.length; ++i) {"
      , "    unsigned char byte = text.bytes[i];"
      , "    char escape[6] = {'\\\\', 'u', '0', '0', 0, 0};"
      , "    size_t width = 2;"
      , "    if (byte >= 32 && byte != 34 && byte != 92) continue;"
      , "    pudu_json_write(out, text.bytes + from, i - from);"
      , "    from = i + 1;"
      , "    switch (byte) {"
      , "      case 8: escape[1] = 'b'; break;"
      , "      case 12: escape[1] = 'f'; break;"
      , "      case 10: escape[1] = 'n'; break;"
      , "      case 13: escape[1] = 'r'; break;"
      , "      case 9: escape[1] = 't'; break;"
      , "      case 34: escape[1] = '\"'; break;"
      , "      case 92: escape[1] = '\\\\'; break;"
      , "      default: escape[4] = hex[byte >> 4]; escape[5] = hex[byte & 15]; width = 6; break;"
      , "    }"
      , "    pudu_json_write(out, escape, width);"
      , "  }"
      , "  pudu_json_write(out, text.bytes + from, text.length - from);"
      , "  pudu_json_write(out, \"\\\"\", 1);"
      , "}"
      , "static void pudu_json_put(pudu_json_writer *out, pudu_box *value, size_t depth) {"
      , "  int tag = value->fields[0].scalar;"
      , "  if (tag == out->null_tag) pudu_json_write(out, \"null\", 4);"
      , "  else if (tag == out->boolean_tag) pudu_json_write(out, value->fields[1].scalar ? \"true\" : \"false\", value->fields[1].scalar ? 4 : 5);"
      , "  else if (tag == out->number_tag) {"
      , "    char digits[24];"
      , "    pudu_int number = value->fields[1].integer;"
      , "    int length = snprintf(digits, sizeof digits, \"%s%\" PRIu64, number.negative && number.bits != 0 ? \"-\" : \"\", pudu_magnitude(number));"
      , "    pudu_json_write(out, digits, (size_t)length);"
      , "  } else if (tag == out->fractional_tag) pudu_json_write(out, value->fields[1].text.bytes, value->fields[1].text.length);"
      , "  else if (tag == out->text_tag) pudu_json_quote(out, value->fields[1].text);"
      , "  else {"
      , "    pudu_items *items = value->fields[1].box->fields[0].items;"
      , "    int list = tag == out->list_tag;"
      , "    pudu_json_write(out, list ? \"[\" : \"{\", 1);"
      , "    for (size_t i = 0; i < items->length; ++i) {"
      , "      if (i != 0) pudu_json_write(out, \",\", 1);"
      , "      pudu_json_line(out, depth + 1);"
      , "      if (list) pudu_json_put(out, items->cells[i].box, depth + 1);"
      , "      else {"
      , "        pudu_json_quote(out, items->cells[i].box->fields[0].text);"
      , "        pudu_json_write(out, \": \", out->pretty ? 2 : 1);"
      , "        pudu_json_put(out, items->cells[i].box->fields[1].box, depth + 1);"
      , "      }"
      , "    }"
      , "    if (items->length != 0) pudu_json_line(out, depth);"
      , "    pudu_json_write(out, list ? \"]\" : \"}\", 1);"
      , "  }"
      , "}"
      , "/* The value as text: compact, or with each member on its own indented line. */"
      , "static pudu_text pudu_json_encode(pudu_box *value, int pretty, int null_tag, int boolean_tag, int number_tag, int fractional_tag, int text_tag, int list_tag, int object_tag) {"
      , "  pudu_json_writer out = {NULL, 0, 0, pretty, null_tag, boolean_tag, number_tag, fractional_tag, text_tag, list_tag};"
      , "  unsigned char *bytes;"
      , "  pudu_text text;"
      , "  (void)object_tag;"
      , "  pudu_json_put(&out, value, 0);"
      , "  text = pudu_text_allocate(out.length, &bytes);"
      , "  if (out.length != 0) memcpy(bytes, out.bytes, out.length);"
      , "  free(out.bytes);"
      , "  return text;"
      , "}"
      ])
  ]
